using namespace cute;

constexpr int THREADS = 256;

__global__ void cute_matvec_kernel(
    const float* A,
    const float* B,
    float* C,
    int M,
    int K)
{
    constexpr int WARPS_PER_BLOCK = THREADS / 32;
    const int tid = static_cast<int>(threadIdx.x);
    const int lane = tid & 31;
    const int warp = tid >> 5;
    const int row = static_cast<int>(blockIdx.x) * WARPS_PER_BLOCK + warp;
    if (row >= M) {
        return;
    }
    const float* row_a = A + static_cast<std::size_t>(row) * K;
    float accum = 0.0f;
    const bool aligned16 =
        ((reinterpret_cast<std::uintptr_t>(row_a) & 0xF) == 0) &&
        ((reinterpret_cast<std::uintptr_t>(B) & 0xF) == 0);
    if (aligned16) {
        const int vector_end = K & ~3;
        for (int k = lane * 4; k < vector_end; k += 32 * 4) {
            const float4 a4 =
                *reinterpret_cast<const float4*>(row_a + k);
            const float4 b4 =
                *reinterpret_cast<const float4*>(B + k);
            accum = fmaf(a4.x, b4.x, accum);
            accum = fmaf(a4.y, b4.y, accum);
            accum = fmaf(a4.z, b4.z, accum);
            accum = fmaf(a4.w, b4.w, accum);
        }
        if (lane == 0) {
            for (int k = vector_end; k < K; ++k) {
                accum = fmaf(row_a[k], B[k], accum);
            }
        }
    } else {
        for (int k = lane; k < K; k += 32) {
            accum = fmaf(row_a[k], B[k], accum);
        }
    }
    for (int offset = 16; offset > 0; offset >>= 1) {
        accum += __shfl_down_sync(0xFFFFFFFFu, accum, offset);
    }
    if (lane == 0) {
        C[row] = accum;
    }
}


